pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 pastUnlockTime, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        // pastUnlockTime must be strictly less than block.timestamp
        vm.warp(1000);
        vm.assume(pastUnlockTime < block.timestamp);

        // First Put with a past _unlockTime; reference will floor to block.timestamp
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.Put{value: 1 ether}(pastUnlockTime);

        // Record the unlockTime after the first Put
        (uint256 firstUnlockTime,) = c.Acc(actor);

        // Second Put with _unlockTime = 0; will be floored to block.timestamp by reference
        vm.warp(block.timestamp + 2000);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.Put{value: 1 ether}(0);

        (uint256 secondUnlockTime,) = c.Acc(actor);

        // General rule: the unlockTime after a Put(0) must be >= the unlockTime that was already stored.
        // The reference holds because the first Put floors past to block.timestamp, and the second Put(0) floors 0 to the newer block.timestamp.
        // The bug version sets firstUnlockTime to the past value, and second Put(0) resets it to an even older past if block.timestamp > 0, violating the invariant.
        assertTrue(secondUnlockTime >= firstUnlockTime);
    }
}

