contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmt, uint256 withdrawAmt, uint256 unlockDelay) public {
        // Bound inputs to avoid overflow and keep them in reasonable domain
        depositAmt = bound(depositAmt, 1 ether, 100 ether);
        withdrawAmt = bound(withdrawAmt, 0.1 ether, 0.9 ether);
        unlockDelay = bound(unlockDelay, 1, 365 days);

        address actor = makeAddr("actor");
        vm.deal(actor, depositAmt);

        // Deposit through Put (msg.value) to set balance and unlockTime
        vm.prank(actor);
        c.Put{value: depositAmt}(block.timestamp + unlockDelay);

        // Warp past unlock time
        vm.warp(block.timestamp + unlockDelay + 1);

        // Record contract balance before Collect
        uint256 balBefore = address(c).balance;

        // Attempt Collect
        vm.prank(actor);
        c.Collect(withdrawAmt);

        uint256 balAfter = address(c).balance;

        // General rule: if withdrawAmt < MinSum (1 ether), the withdrawal should be denied
        // so contract balance should not drop. If depositAmt >= MinSum, it's possible
        // but the bug allows it even when depositAmt < MinSum (specifically acc.balance < MinSum)
        // Here we check the invariant: 
        // If original user balance < MinSum, Collect MUST revert, so balance unchanged.
        // We capture this by checking: if (depositAmt < c.MinSum()) assert(balBefore == balAfter)
        // Otherwise no assertion needed (or it's allowed).
        // Since the fuzzer can explore depositAmt < MinSum, we assert that in that case balance unchanged.
        if (depositAmt < c.MinSum()) {
            assertEq(balBefore, balAfter);
        }
    }
}

