pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, uint256 unlockTime, uint256 warpTime) public {
        // Bound inputs to admissible domain
        depositAmount = bound(depositAmount, 1 ether, 100 ether);
        collectAmount = bound(collectAmount, 1 ether, 100 ether);
        unlockTime = bound(unlockTime, 0, 365 days);
        warpTime = bound(warpTime, 0, 365 days);

        address actor = address(0x1234);
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Put{value: depositAmount}(block.timestamp + unlockTime);

        vm.warp(block.timestamp + warpTime);

        uint256 balanceBefore = address(c).balance;

        bool collected;
        vm.prank(actor);
        try c.Collect(collectAmount) {
            collected = true;
        } catch {
            collected = false;
        }

        uint256 balanceAfter = address(c).balance;
        uint256 minSum = c.MinSum();

        // Universal property: If balance after collect drops below MinSum, it must be that Collect reverted (no state change)
        // OR the unlockTime had passed (making the withdraw permissible).
        // Formally: if 'collected' is true and balanceAfter < minSum, then unlockTime must have been <= block.timestamp.
        // The bug removes the unlockTime check, so collect can succeed with balanceAfter < minSum even when unlockTime > block.timestamp.
        if (!collected) {
            // If it reverted, state unchanged, balanceBefore == balanceAfter (provided no other call interferes).
            // This condition always holds for both versions.
            assertTrue(balanceBefore == balanceAfter || balanceAfter >= minSum);
        } else {
            // Collect succeeded: either unlock time passed OR balance remains >= minSum.
            // Reference: if unlockTime > block.timestamp, require(acc.balance>=MinSum && ... && block.timestamp>acc.unlockTime) fails -> revert.
            // Bug: allows success even if unlockTime > block.timestamp, and balanceAfter may drop below minSum.
            assertTrue((block.timestamp > block.timestamp + unlockTime - warpTime) || balanceAfter >= minSum);
        }
    }
}

